            if dang=='1':
                # Random các thông số của parabol: f(x) = -x^2 + Sx - P với 2 nghiệm phân biệt a và b
                a = random.randint(1, 3)
                d = random.randint(2, 5) # khoảng cách giữa 2 nghiệm
                b = a + d
                S_val = a + b
                P_val = a * b
                U = random.choice([10, 15, 20]) # đơn vị trên trục tọa độ (mét)
                U_sq = U**2

                x = sp.Symbol('x')
                fx = -x**2 + S_val*x - P_val
                Sx = (S_val - 2*x) * fx
                Sx_expanded = sp.expand(Sx)
                S_prime = sp.diff(Sx_expanded, x)

                # Tìm nghiệm đạo hàm (lấy nghiệm x < S/2)
                roots = sp.solve(S_prime, x)
                x_val = None
                for r in roots:
                    if r.evalf() < S_val / 2.0:
                        x_val = r
                        break

                # Tính kích thước và diện tích lớn nhất trên tọa độ
                CD_val = sp.simplify(S_val - 2*x_val)
                AD_val = sp.simplify(fx.subs(x, x_val))
                S_max = sp.simplify(CD_val * AD_val)

                # Tính diện tích thực tế (nhân với bình phương tỷ lệ hệ trục)
                actual_area = S_max * U_sq
